/// دعاء مأثور عن أهل البيت (عليهم السلام).
class AhlulbaytDua {
  final String id;

  /// عنوان الدعاء (دعاء كميل، مكارم الأخلاق…).
  final String title;

  /// المنسوب إليه.
  final String attributedTo;

  /// تصنيف الدعاء (الصحيفة السجادية، ليلة الجمعة، قضاء الحوائج…).
  final String category;

  /// نبذة عن الدعاء وفضله ومناسبته.
  final String summary;

  /// النص الكامل متصلاً دون تقطيع.
  final String content;

  const AhlulbaytDua({
    required this.id,
    required this.title,
    required this.attributedTo,
    required this.category,
    required this.summary,
    required this.content,
  });
}

